int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state = 0;
    int ret;

    // Initialize libgpiod
    ret = gpiod_chip_open_by_name("gpio", &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_to_str(ret));
        return EXIT_FAILURE;
    }

    // Request GPIO line
    ret = gpiod_line_request_any(chip, "GPIO", GPIO_PIN, 0, &line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_error_to_str(ret));
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    ret = gpiod_line_direction_output(line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", gpiod_error_to_str(ret));
        gpiod_line_release(line);
        gpiod_chip_put(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle GPIO state
        state = !state;
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO state: %s\n", gpiod_error_to_str(ret));
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }

        // Report state
        printf("GPIO %d state: %d\n", GPIO_PIN, state);

        // Sleep for 5 seconds
        sleep(DELAY_SECONDS);
    }

    // Cleanup on exit
    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

