#include <linux/i2c-dev.h>
#include <string.h>

#define MLX90614_I2C_ADDR 0x5a
#define MLX90614_REG_AMBIENT_TEMP 0x00
#define MLX90614_REG_OBJECT_TEMP 0x01

int read_temperature(int fd) {
    int ambient_temp, object_temp;
    char buffer[2];

    // Read ambient temperature
    if (read(fd, buffer, 1) != 1) {
        perror("Error reading ambient temperature");
        return -1;
    }
    ambient_temp = (buffer[0] << 8) | buffer[0];

    // Read object temperature
    if (read(fd, buffer, 1) != 1) {
        perror("Error reading object temperature");
        return -1;
    }
    object_temp = (buffer[0] << 8) | buffer[0];

    // Convert to Celsius
    ambient_temp = (ambient_temp * 0.02) - 273.15;
    object_temp = (object_temp * 0.02) - 273.15;

    printf("Ambient Temperature: %.2f°C, Object Temperature: %.2f°C\n", ambient_temp, object_temp);

    return 0;
}

int main() {
    int fd;
    char device_path[20];

    // Open I2C device
    snprintf(device_path, sizeof(device_path), "/dev/i2c-%d", 1);
    fd = open(device_path, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Check if the device is present
    if (ioctl(fd, I2C_SLAVE, MLX90614_I2C_ADDR) < 0) {
        perror("Error setting I2C device address");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_temperature(fd) < 0) {
            break;
        }
        sleep(5);
    }

    // Close I2C device
    close(fd);

    return 0;
}

