#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_MS 10000

static void usage(const char *progname) {
    fprintf(stderr, "Usage: %s\n", progname);
    exit(EXIT_FAILURE);
}

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void cleanup(struct gpiod_chip *chip, struct gpiod_line *trig_line, struct gpiod_line *echo_line) {
    if (echo_line) {
        gpiod_line_request_release(echo_line);
    }
    if (trig_line) {
        gpiod_line_request_release(trig_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int trig_value, echo_value;
    unsigned long start_time, end_time;
    unsigned long duration;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    trig_line = gpiod_line_request(chip, TRIG_PIN, "trig_line", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trig_line) {
        handle_error("Failed to request TRIG line");
    }

    echo_line = gpiod_line_request(chip, ECHO_PIN, "echo_line", GPIOD_LINE_DIRECTION_INPUT);
    if (!echo_line) {
        handle_error("Failed to request ECHO line");
    }

    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 0);
        usleep(2);
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo
        start_time = gpiod_line_get_value(echo_line);
        while (gpiod_line_get_value(echo_line) == 0 && (end_time - start_time) < TIMEOUT_MS) {
            usleep(100);
        }

        if ((end_time - start_time) >= TIMEOUT_MS) {
            printf("Timeout: Echo not received within %d ms\n", TIMEOUT_MS);
            continue;
        }

        // Calculate distance
        duration = end_time - start_time;
        float distance = (duration / 2.0) * 34300.0 / 1000000.0; // Speed of sound is approximately 343 m/s
        printf("Distance: %.2f cm\n", distance);

        sleep(60);
    }

    cleanup(chip, trig_line, echo_line);
    return 0;
}

