#include <linux/i2c-dev.h>
#include <string.h>

#define SI7021_ADDR 0x40
#define SI7021_REG_TEMP 0x00
#define SI7021_REG_HUMIDITY 0x01

int read_i2c_device(int fd, uint8_t reg, uint8_t *data) {
    int ret;

    // Write the register address
    ret = write(fd, &reg, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read the data
    ret = read(fd, data, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

int main() {
    int fd;
    uint8_t data[2];
    int ret;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set the I2C address
    ret = ioctl(fd, I2C_SLAVE, SI7021_ADDR);
    if (ret < 0) {
        perror("Error setting I2C address");
        close(fd);
        return 1;
    }

    while (1) {
        // Read temperature
        ret = read_i2c_device(fd, SI7021_REG_TEMP, data);
        if (ret < 0) {
            perror("Error reading temperature");
            close(fd);
            return 1;
        }

        // Read humidity
        ret = read_i2c_device(fd, SI7021_REG_HUMIDITY, data);
        if (ret < 0) {
            perror("Error reading humidity");
            close(fd);
            return 1;
        }

        // Check validity of readings (example: temperature should be between -40 and 125 degrees Celsius)
        if ((data[0] < 0x80 && (data[0] < 0x00 || data[0] > 0x7F)) || (data[0] >= 0x80 && (data[0] < 0x80 || data[0] > 0xFF))) {
            fprintf(stderr, "Invalid temperature reading\n");
            continue;
        }

        // Print the readings
        printf("Temperature: %d, Humidity: %d\n", data[0], data[1]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

