int main() {
    int fd;
    char filename[16];
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msg_read[1];
    uint8_t buffer[2];
    int i;

    // Open the I2C device
    sprintf(filename, "/dev/i2c-%d", 1); // Assuming I2C bus 1
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    // Check if the device is present
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Configure the ADC for single-shot mode
    buffer[0] = 0x00; // Configuration register
    buffer[1] = 0x86; // Single-shot mode, gain 1x, data rate 860 samples/sec
    msg_read[0].addr = I2C_ADDR;
    msg_read[0].flags = 0;
    msg_read[0].len = 2;
    msg_read[0].buf = buffer;

    msg.msgs = msg_read;
    msg.nmsgs = 1;

    // Write configuration to the ADC
    if (ioctl(fd, I2C_RDWR, &msg) < 0) {
        perror("Failed to write configuration to ADC");
        close(fd);
        return 1;
    }

    // Read the ADC value
    msg_read[0].addr = I2C_ADDR;
    msg_read[0].flags = 0;
    msg_read[0].len = 2;
    msg_read[0].buf = buffer;

    msg.msgs = msg_read;
    msg.nmsgs = 1;

    for (i = 0; i < NUM_READINGS; i++) {
        if (ioctl(fd, I2C_RDWR, &msg) < 0) {
            perror("Failed to read from ADC");
            close(fd);
            return 1;
        }

        // Combine the two bytes into a 16-bit value
        int16_t adc_value = (buffer[1] << 8) | buffer[0];

        // Print the ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait for 1 second before the next reading
        sleep(1);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

