int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open(NULL, &chip);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_to_str(ret));
        exit(EXIT_FAILURE);
    }

    // Request the trigger (TRIG) line
    ret = gpiod_line_request(chip, TRIG_PIN, "trig", &trig_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", gpiod_error_to_str(ret));
        cleanup(chip, NULL, NULL);
        exit(EXIT_FAILURE);
    }

    // Request the echo line
    ret = gpiod_line_request(chip, ECHO_PIN, "echo", &echo_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line: %s\n", gpiod_error_to_str(ret));
        cleanup(chip, trig_line, NULL);
        exit(EXIT_FAILURE);
    }

    // Set TRIG line as output
    ret = gpiod_line_direction_output(trig_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG line direction: %s\n", gpiod_error_to_str(ret));
        cleanup(chip, trig_line, echo_line);
        exit(EXIT_FAILURE);
    }

    // Set ECHO line as input
    ret = gpiod_line_direction_input(echo_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to set ECHO line direction: %s\n", gpiod_error_to_str(ret));
        cleanup(chip, trig_line, echo_line);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send a trigger pulse
        ret = gpiod_line_set_value(trig_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set TRIG line value: %s\n", gpiod_error_to_str(ret));
            cleanup(chip, trig_line, echo_line);
            exit(EXIT_FAILURE);
        }

        usleep(10); // 10us pulse

        ret = gpiod_line_set_value(trig_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set TRIG line value: %s\n", gpiod_error_to_str(ret));
            cleanup(chip, trig_line, echo_line);
            exit(EXIT_FAILURE);
        }

        // Wait for echo pulse
        int echo_value = gpiod_line_get_value(echo_line);
        if (echo_value < 0) {
            fprintf(stderr, "Failed to get ECHO line value: %s\n", gpiod_error_to_str(echo_value));
            cleanup(chip, trig_line, echo_line);
            exit(EXIT_FAILURE);
        }

        // If echo is not detected, give up and continue
        if (echo_value == 0) {
            printf("Echo not detected\n");
            continue;
        }

        // Measure the duration of the echo pulse
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
        }

        // Calculate the distance
        double duration = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        double distance = (duration * 34300) / 2; // Speed of sound in cm/s

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup on exit
    cleanup(chip, trig_line, echo_line);

    return 0;
}

