#include <signal.h>

#define BAUDRATE 115200
#define BUFFER_SIZE 1024

static volatile sig_atomic_t stop_flag = 0;

void cleanup(int signum) {
    stop_flag = 1;
    tcflush(0, TCIOFLUSH);
    close(0);
    exit(1);
}

int main() {
    struct termios options;
    int fd;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Register cleanup function for SIGINT (Ctrl+C)
    signal(SIGINT, cleanup);

    // Open the serial port
    fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        exit(1);
    }

    // Configure the serial port
    if (tcgetattr(fd, &options) == -1) {
        perror("Error getting termios attributes");
        close(fd);
        exit(1);
    }

    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        perror("Error setting termios attributes");
        close(fd);
        exit(1);
    }

    // Duplicate file descriptor 0 to the serial port
    if (dup2(fd, 0) == -1) {
        perror("Error duplicating file descriptor");
        close(fd);
        exit(1);
    }

    // Read from the serial port and print to stdout
    while (!stop_flag) {
        bytes_read = read(0, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            write(1, buffer, bytes_read);
        }
    }

    // Cleanup
    close(0);
    return 0;
}

