#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO_PIN 4

static void usage(const char *progname) {
    fprintf(stderr, "Usage: %s <state> (0 or 1)\n", progname);
    exit(EXIT_FAILURE);
}

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        usage(argv[0]);
    }

    int state = atoi(argv[1]);
    if (state != 0 && state != 1) {
        usage(argv[0]);
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open the GPIO chip
    if (gpiod_chip_open(NULL, &chip) < 0) {
        handle_error("Failed to open GPIO chip");
    }

    // Find the GPIO line
    if (gpiod_line_request_any(chip, "gpio%d", GPIO_PIN, "example", 0, &line) < 0) {
        gpiod_chip_close(chip);
        handle_error("Failed to request GPIO line");
    }

    // Set the direction to output
    if (gpiod_line_direction_output(line) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        handle_error("Failed to set GPIO direction to output");
    }

    // Set the state
    if (gpiod_line_set_value(line, state) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        handle_error("Failed to set GPIO state");
    }

    printf("GPIO %d set to %d\n", GPIO_PIN, state);

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

