        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int duty_cycle = 50; // 50% duty cycle

    while (1) {
        if (gpioPWM(GPIO_4, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO 4.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpioPWM(GPIO_12, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO 12.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpioPWM(GPIO_18, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO 18.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("PWM set to %d%% on GPIO 4, 12, 18.\n", duty_cycle);

        sleep(1); // Wait for 1 second

        // Reset PWM to 0% duty cycle
        if (gpioPWM(GPIO_4, 0) < 0) {
            fprintf(stderr, "Failed to reset PWM on GPIO 4.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpioPWM(GPIO_12, 0) < 0) {
            fprintf(stderr, "Failed to reset PWM on GPIO 12.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpioPWM(GPIO_18, 0) < 0) {
            fprintf(stderr, "Failed to reset PWM on GPIO 18.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("PWM reset to 0%% on GPIO 4, 12, 18.\n");
    }

    cleanup(); // This will be reached only if the program is interrupted
    return EXIT_SUCCESS;
}

