#define HTU21D_MEAS_TEMPERATURE 0xE3
#define HTU21D_READ_STATUS 0xE0

int read_htu21d(int file_descriptor) {
    unsigned char data[3];
    int result = -1;

    // Request humidity measurement
    if (write(file_descriptor, &HTU21D_MEAS_HUMIDITY, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete
    usleep(250000);

    // Read humidity data
    if (read(file_descriptor, data, 3) != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Check status byte
    if ((data[0] & 0x80) == 0) {
        printf("Humidity measurement failed\n");
        return -1;
    }

    // Calculate humidity
    unsigned short humidity = (data[1] << 8) | data[0];
    printf("Humidity: %u\n", humidity);

    // Request temperature measurement
    if (write(file_descriptor, &HTU21D_MEAS_TEMPERATURE, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete
    usleep(250000);

    // Read temperature data
    if (read(file_descriptor, data, 3) != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Check status byte
    if ((data[0] & 0x80) == 0) {
        printf("Temperature measurement failed\n");
        return -1;
    }

    // Calculate temperature
    unsigned short temperature = (data[1] << 8) | data[0];
    printf("Temperature: %u\n", temperature);

    result = 0;
    return result;
}

