#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

int main() {
    int fd;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    void *image_buffer;
    FILE *image_file;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Get the camera format
    if (ioctl(fd, VIDIOC_QUERYCAP, &fmt) < 0) {
        perror("Failed to query camera capabilities");
        close(fd);
        return 1;
    }

    // Set the image format to JPEG
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set image format");
        close(fd);
        return 1;
    }

    // Request buffers
    req.count = 2;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    // Map the buffers
    unsigned long length;
    struct v4l2_buffer mapped_buffer;
    for (int i = 0; i < req.count; i++) {
        mapped_buffer.index = i;
        mapped_buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        mapped_buffer.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QUERYBUF, &mapped_buffer) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return 1;
        }
        length = mapped_buffer.length;
        image_buffer = mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, mapped_buffer.m.offset);
        if (image_buffer == MAP_FAILED) {
            perror("Failed to map buffer");
            close(fd);
            return 1;
        }
    }

    // Start streaming
    struct v4l2_requestbuffers start_req;
    start_req.count = 1;
    start_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    start_req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_STREAMON, &start_req) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return 1;
    }

    // Capture image
    struct v4l2_buffer capture_buf;
    capture_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    capture_buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_DQBUF, &capture_buf) < 0) {
        perror("Failed to capture image");
        close(fd);
        return 1;
    }

    // Open file to save image
    image_file = fopen(IMAGE_FILE, "wb");
    if (!image_file) {
        perror("Failed to open image file");
        close(fd);
        return 1;
    }

    // Write image data to file
    fwrite(image_buffer, capture_buf.bytesused, 1, image_file);
    fclose(image_file);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, NULL) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        return 1;
    }

    // Unmap buffers
    for (int i = 0; i < req.count; i++) {
        munmap(image_buffer, length);
    }

    // Close the camera device
    close(fd);

    printf("Image captured and saved to %s\n", IMAGE_FILE);
    return 0;
}

