#define I2C_ADDR 0x3C
#define BUFFER_SIZE 128

int i2c_fd;

void init_i2c() {
    char filename[10];
    sprintf(filename, "/dev/i2c-%d", 1); // Assuming I2C bus 1

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void write_to_display(const char *message) {
    int len = strlen(message);
    if (len > BUFFER_SIZE) {
        fprintf(stderr, "Message too long for buffer\n");
        return;
    }

    if (write(i2c_fd, message, len) != len) {
        perror("Failed to write to display");
    }
}

void cleanup() {
    close(i2c_fd);
}

int main() {
    init_i2c();

    while (1) {
        char buffer[BUFFER_SIZE];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        snprintf(buffer, BUFFER_SIZE, "Time: %02d:%02d:%02d", tm->tm_hour, tm->tm_min, tm->tm_sec);
        write_to_display(buffer);

        usleep(100000); // Sleep for 0.1 seconds
    }

    cleanup();
    return 0;
}

