#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 3
#define BUFFER_SIZE 8192

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void release_buffers(struct v4l2_buffer *buffers, int count) {
    for (int i = 0; i < count; i++) {
        if (munmap(buffers[i].m.mem_offset, buffers[i].length) < 0) {
            handle_error("Failed to munmap buffer");
        }
    }
}

static void release_device(int fd) {
    if (close(fd) < 0) {
        handle_error("Failed to close device");
    }
}

int main() {
    const char *device_name = "/dev/video0";
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;
    char buffer[BUFFER_SIZE];
    char filename[256];
    int i;

    // Open the device
    fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    // Check if the device is a video device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        handle_error("Failed to query device capabilities");
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        handle_error("Device is not a video capture device");
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        handle_error("Failed to set format");
    }

    // Request buffers
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        handle_error("Failed to request buffers");
    }

    // Allocate buffers
    struct v4l2_buffer buffers[BUFFER_COUNT];
    for (i = 0; i < BUFFER_COUNT; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) < 0) {
            handle_error("Failed to query buffer");
        }
        buffers[i].m.mem_offset = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (buffers[i].m.mem_offset == MAP_FAILED) {
            handle_error("Failed to mmap buffer");
        }
    }

    // Start streaming
    for (i = 0; i < BUFFER_COUNT; i++) {
        buffers[i].index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) < 0) {
            handle_error("Failed to queue buffer");
        }
    }
    for (i = 0; i < BUFFER_COUNT; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMON, &buffers[i]) < 0) {
            handle_error("Failed to start streaming");
        }
    }

    // Capture and save images
    while (1) {
        int index;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            handle_error("Failed to dequeue buffer");
        }

        // Save the image
        sprintf(filename, "image_%d.yuv", buf.index);
        FILE *file = fopen(filename, "wb");
        if (!file) {
            handle_error("Failed to open file for writing");
        }
        fwrite(buf.m.mem_offset, 1, buf.bytesused, file);
        fclose(file);

        // Return the buffer to the queue
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("Failed to requeue buffer");
        }

        // Sleep for 0.05 seconds
        usleep(50000);
    }

    // Clean up
    release_buffers(buffers, BUFFER_COUNT);
    release_device(fd);

    return 0;
}

