int read_bme280_data(unsigned char reg, unsigned char *data) {
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        perror("read");
        return -1;
    }

    return 0;
}

int main() {
    char i2c_device_path[100];
    unsigned char data[3];
    unsigned int pressure, temperature, humidity;

    signal(SIGINT, handle_sigint);

    sprintf(i2c_device_path, "/dev/i2c-%d", 1);
    i2c_fd = open(i2c_device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
    }

    while (1) {
        if (read_bme280_data(BME280_REG_PRESSURE, data) < 0) {
            perror("Failed to read pressure data");
            cleanup();
        }

        pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

        if (read_bme280_data(BME280_REG_TEMPERATURE, data) < 0) {
            perror("Failed to read temperature data");
            cleanup();
        }

        temperature = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);

        if (read_bme280_data(BME280_REG_HUMIDITY, data) < 0) {
            perror("Failed to read humidity data");
            cleanup();
        }

        humidity = (data[0] << 8) | data[1];

        printf("Pressure: %u hPa, Temperature: %u °C, Humidity: %u %%\n",
               pressure, temperature, humidity);

        sleep(5);
    }

    cleanup();

    return 0;
}

