#define MQTT_BROKER "broker.hivemq.com"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/readings"
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "raspberry_pi_sensor"

static int sensor_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int sensor_value = 0;

void handle_signal(int signum) {
    if (sensor_fd != -1) {
        close(sensor_fd);
        sensor_fd = -1;
    }
    if (line != NULL) {
        gpiod_line_put(line);
        line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_put(chip);
        chip = NULL;
    }
    exit(signum);
}

void publish_sensor_reading(const char *topic, const char *payload) {
    MQTTClient *client = NULL;
    MQTTClient_connectData conn_data = MQTTClient_connectData_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;

    conn_data.keepAliveInterval = MQTT_KEEPALIVE;
    conn_data.cleansession = 1;
    conn_data.clientID = MQTT_CLIENT_ID;

    client = MQTTClient_create(MQTT_BROKER, MQTT_CLIENT_ID, MQTT_PORT, NULL, NULL);
    if (client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return;
    }

    if (MQTTClient_connect(client, &conn_data) != MQTT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(client);
        return;
    }

    pubmsg.payload = (void*)payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    if (MQTTClient_publishMessage(client, topic, &pubmsg, NULL) != MQTT_SUCCESS) {
        fprintf(stderr, "Failed to publish message\n");
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(client);
}

int main() {
    int ret;
    char payload[64];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open("/dev/gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (gpiod_line_request_any(chip, "sensor", GPIOD_LINE_DIRECTION_IN, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_put(chip);
        return 1;
