    sensor_fd = gpiod_line_get_fd(line);
    if (sensor_fd < 0) {
        perror("Failed to get file descriptor for GPIO line");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return 1;
    }

    while (1) {
        ret = read(sensor_fd, &sensor_value, sizeof(sensor_value));
        if (ret < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue; // Device not responding, give up and try again
            }
            perror("Failed to read sensor value");
            break;
        }

        if (sensor_value < 0 || sensor_value > 1023) {
            fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
