        }

        sprintf(payload, "%d", sensor_value);
        publish_sensor_reading(MQTT_TOPIC, payload);

        usleep(10000); // Sleep for 0.01 seconds
    }

    handle_signal(0); // Clean up and exit
    return 0;
}

