        for (int i = 0; i < NUM_PINS; i++) {
            int duty_cycle = (rand() % (PWM_MAX - PWM_MIN + 1)) + PWM_MIN;
            if (gpioPWM(GPIO_PINS[i], duty_cycle) < 0) {
