#include <linux/videodev2.h>

#define BUFFER_COUNT 3
#define IMAGE_FILE "captured_image.jpg"

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void release_resources(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    int fd;
    struct v4l2_buffer buf;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    char *buffers[BUFFER_COUNT];
    int i;

    // Open the video device
    fd = open("/dev/video0", O_RDWR /* required */ | O_NONBLOCK, 0);
    if (fd == -1) {
        handle_error("Failed to open video device");
    }

    // Set the format to JPEG
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        handle_error("Failed to set format");
    }

    // Request buffers
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        handle_error("Failed to request buffers");
    }

    // Map the buffers
    for (i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            handle_error("Failed to query buffer");
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            handle_error("Failed to map buffer");
        }
    }

    // Start streaming
    for (i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            handle_error("Failed to queue buffer");
        }
    }

    for (i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_STREAMON, &buf) == -1) {
            handle_error("Failed to start streaming");
        }
    }

    // Capture and save images
    while (1) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            handle_error("Failed to dequeue buffer");
        }

        // Save the image to a file
        FILE *file = fopen(IMAGE_FILE, "wb");
        if (file == NULL) {
            handle_error("Failed to open file for writing");
        }
        fwrite(buffers[buf.index], buf.bytesused, 1, file);
        fclose(file);

        // Queue the buffer back
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            handle_error("Failed to queue buffer back");
        }
    }

    // Clean up
    for (i = 0; i < BUFFER_COUNT; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_STREAMOFF, &buf) == -1) {
            handle_error("Failed to stop streaming");
        }
        if (munmap(buffers[i], buf.length) == -1) {
            handle_error("Failed to unmap buffer");
        }
    }

    release_resources(fd);

    return 0;
}

