    int fd = open(device_name, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        handle_error("Failed to query device capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is not a video capture device\n", device_name);
        release_device(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        handle_error("Failed to set format");
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        handle_error("Failed to request buffers");
    }

    struct v4l2_buffer buf;
    struct v4l2_buffer *buffers = malloc(sizeof(buf) * req.count);
    if (!buffers) {
        handle_error("Failed to allocate memory for buffers");
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            handle_error("Failed to query buffer");
        }

        buffers[i].length = buf.length;
        buffers[i].m.memory = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].m.memory == MAP_FAILED) {
            handle_error("Failed to mmap buffer");
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        handle_error("Failed to start streaming");
    }

    int ret = 0;
    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            handle_error("Failed to dequeue buffer");
        }

        if (buf.flags & V4L2_BUF_FLAG_EOF) {
            break;
        }

        FILE *file = fopen("captured_image.yuv", "wb");
        if (!file) {
            handle_error("Failed to open output file");
        }

        fwrite(buffers[buf.index].m.memory, 1, buf.bytesused, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            handle_error("Failed to queue buffer");
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        handle_error("Failed to stop streaming");
    }

    release_buffers(buffers, req.count);
    free(buffers);
    release_device(fd);

    return ret;
}

