void handle_exit(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    mraa_aio_close(aio_context);
    mraa_spi_stop(spi_context);
    gpiod_line_request_free(spi_cs);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(client);
    exit(0);
}

int read_sensor() {
    uint8_t cmd = (sensor_channel << MCP3008_CHANNEL_SHIFT) | MCP3008_READ;
    uint8_t data[3];

    mraa_spi_write(spi_context, &cmd, 1);
    mraa_spi_read(spi_context, data, 3);

    int result = ((data[1] & MCP3008_DATA_MASK) << 8) | (data[2] & MCP3008_DATA_MASK);
    return result;
}

void publish_reading(int reading) {
    char message[64];
    snprintf(message, sizeof(message), "%d", reading);

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, (void*)message, strlen(message), 0, false, &token);
    if (rc != MQTT_SUCCESS) {
        printf("Failed to publish message: %s\n", MQTTClient_strerror(client, rc));
    }
}

int main() {
    int rc;

    // Initialize GPIO and SPI
    if ((rc = gpiod_line_request(NULL, "SPI0_CE0", "SPI CS", 0, GPIOD_LINE_DIRECTION_OUTPUT, &spi_cs)) < 0) {
        printf("Failed to request SPI CS line: %s\n", gpiod_line_strerror(rc));
        return 1;
    }

    if ((rc = gpiod_line_set_value(spi_cs, 0)) < 0) {
        printf("Failed to set SPI CS line value: %s\n", gpiod_line_strerror(rc));
        return 1;
    }

    if ((spi_fd = mraa_spi_init(MCP3008_SPI_CHANNEL)) < 0) {
        printf("Failed to initialize SPI: %s\n", mraa_result_to_string(rc));
        return 1;
    }

    if ((rc = mraa_spi_frequency(spi_fd, MCP3008_SPI_SPEED)) < 0) {
        printf("Failed to set SPI frequency: %s\n", mraa_result_to_string(rc));
        return 1;
    }

    if ((rc = mraa_spi_mode(spi_fd, 0)) < 0) {
        printf("Failed to set SPI mode: %s\n", mraa_result_to_string(rc));
        return 1;
    }

    // Initialize MQTT client
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = true;
    conn_opts.userName = "username";
    conn_opts.password = "password";

    rc = MQTTClient_create(&client, MQTT_HOST, MQTT_PORT, NULL, NULL);
    if (rc != MQTT_SUCCESS) {
        printf("Failed to create MQTT client: %s\n", MQTTClient_strerror(client, rc));
        return 1;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTT_SUCCESS) {
        printf("Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(client, rc));
        return 1;
    }

    // Read sensor and publish reading
    int reading = read_sensor();
    publish_reading(reading);

    // Clean up
    handle_exit(0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 3
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void init_device(int *fd, struct v4l2_format *format) {
    int result;

    *fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (*fd < 0) {
        handle_error("Failed to open video device");
    }

    result = ioctl(*fd, VIDIOC_QUERYCAP, format);
    if (result < 0) {
        handle_error("Failed to query video device capabilities");
    }

    if (!(format->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        handle_error("Device does not support video capture");
    }

    format->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format->fmt.pix.width = IMAGE_WIDTH;
    format->fmt.pix.height = IMAGE_HEIGHT;
    format->fmt.pix.pixelformat = IMAGE_FORMAT;
    format->fmt.pix.field = V4L2_FIELD_INTERLACED;

    result = ioctl(*fd, VIDIOC_S_FMT, format);
    if (result < 0) {
        handle_error("Failed to set video format");
    }
}

static void init_buffers(int fd, struct v4l2_buffer *buffer) {
    int result;

    buffer->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer->memory = V4L2_MEMORY_MMAP;

    for (int i = 0; i < BUFFER_COUNT; i++) {
        result = ioctl(fd, VIDIOC_QUERYBUF, buffer);
        if (result < 0) {
            handle_error("Failed to query buffer");
        }

        buffer->index = i;
        result = ioctl(fd, VIDIOC_REQBUFS, buffer);
        if (result < 0) {
            handle_error("Failed to request buffers");
        }
    }
}

static void start_capturing(int fd) {
    int result;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    result = ioctl(fd, VIDIOC_STREAMON, &type);
    if (result < 0) {
        handle_error("Failed to start capturing");
    }
}

static void stop_capturing(int fd) {
    int result;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    result = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (result < 0) {
        handle_error("Failed to stop capturing");
    }
}

static void capture_image(int fd, char *filename) {
    int result;
    struct v4l2_buffer buffer;
    char *buffer_start;
    FILE *file;

    buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer.memory = V4L2_MEMORY_MMAP;

    file = fopen(filename, "wb");
    if (!file) {
        handle_error("Failed to open file for writing");
    }

    while (1) {
        result = ioctl(fd, VIDIOC_DQBUF, &buffer);
        if (result < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            handle_error("Failed to dequeue buffer");
        }

        if (buffer.flags & V4L2_BUF_FLAG_EOF) {
            break;
        }

        buffer_start = mmap(NULL, buffer.length, PROT_READ, MAP_SHARED, fd, buffer.m.offset);
        if (buffer_start == MAP_FAILED) {
            handle_error("Failed to map buffer");
        }

        fwrite(buffer_start, buffer.bytesused, 1, file);
        munmap(buffer_start, buffer.length);

        result = ioctl(fd, VIDIOC_QBUF, &buffer);
        if (result < 0) {
            handle_error("Failed to queue buffer");
        }
    }

    fclose(file);
}

int main() {
    int fd;
    struct v4l2_format format;
    struct v4l2_buffer buffer;

    init_device(&fd, &format);
    init_buffers(fd, &buffer);
    start_capturing(fd);
    capture_image(fd, "captured_image.yuv");
    stop_capturing(fd);

    close(fd);
    return 0;
}

