int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    // Request trigger line (output)
    trigger_line = gpiod_line_request(chip, HC_SR04_TRIGGER_PIN, "HC-SR04 Trigger", 0, GPIOD_LINE_DIRECTION_OUT);
    if (!trigger_line) {
        handle_error("Failed to request trigger line");
    }

    // Request echo line (input)
    echo_line = gpiod_line_request(chip, HC_SR04_ECHO_PIN, "HC-SR04 Echo", 0, GPIOD_LINE_DIRECTION_IN);
    if (!echo_line) {
        handle_error("Failed to request echo line");
    }

    // Main loop
    while (1) {
        // Send trigger pulse
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret < 0) {
            handle_error("Failed to set trigger line");
        }
        usleep(10); // 10 microsecond delay
        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret < 0) {
            handle_error("Failed to set trigger line");
        }

        // Wait for echo pulse
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            handle_error("Failed to get echo line value");
        }
        if (ret != 1) {
            printf("Echo line not responding\n");
            continue;
        }

        // Measure pulse duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (end.tv_sec - start.tv_sec > 1) {
                printf("Echo pulse duration exceeded 1 second\n");
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate distance
        double duration = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        double distance = (duration * 34300) / 2; // Speed of sound in cm/s
        printf("Distance: %.2f cm\n", distance);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup(chip, trigger_line, echo_line);

    return 0;
}

