#define SHT31_MEAS_TEMP_HUM_DELAY 1000000 // 1 second delay

int read_temperature_humidity(int file_desc) {
    unsigned char data[4];
    int ret;

    // Start measurement
    ret = write(file_desc, &SHT31_MEAS_TEMP_HUM, 1);
    if (ret != 1) {
        perror("Failed to start measurement");
        return -1;
    }

    // Wait for measurement to complete
    usleep(SHT31_MEAS_TEMP_HUM_DELAY);

    // Read data
    ret = read(file_desc, data, 4);
    if (ret != 4) {
        perror("Failed to read data");
        return -1;
    }

    // Check CRC
    unsigned char crc = data[3];
    unsigned char calculated_crc = (data[0] ^ data[1] ^ data[2]);
    if (crc != calculated_crc) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Calculate temperature and humidity
    float temperature = (data[0] << 8) | data[1];
    float humidity = (data[2] << 8) | data[3];

    // Print the readings
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature / 100.0, humidity / 100.0);

    return 0;
}

