#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 3
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

int main() {
    char *dev_name = "/dev/video0";
    char *image_file = "captured_image.jpg";

    int fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is not a video capture device\n", dev_name);
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_ANY;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    unsigned long long int buffer_length;
    void *buffers[BUFFER_COUNT];

    for (int i = 0; i < BUFFER_COUNT; i++) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return 1;
        }

        buffer_length = buf.length;
        buffers[i] = mmap(NULL, buffer_length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            close(fd);
            return 1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return 1;
    }

    int ret = 0;
    while (ret == 0) {
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("Failed to dequeue buffer");
            ret = 1;
        }

        if (buf.bytesused > 0) {
            FILE *image_file_ptr = fopen(image_file, "wb");
            if (image_file_ptr == NULL) {
                perror("Failed to open image file");
                ret = 1;
            } else {
                fwrite(buffers[buf.index], 1, buf.bytesused, image_file_ptr);
                fclose(image_file_ptr);
            }
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            ret = 1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        ret = 1;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (munmap(buffers[i], buffer_length) < 0) {
            perror("Failed to unmap buffer");
            ret = 1;
        }
    }

    close(fd);
    return ret;
}

