int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig, *echo;
    int ret;

    // Open the gpiod chip
    ret = gpiod_chip_open(NULL, &chip);
    if (ret < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO lines
    ret = gpiod_line_request(chip, TRIG_PIN, "trig", GPIOD_LINE_DIRECTION_OUTPUT, &trig);
    if (ret < 0) {
        perror("gpiod_line_request (trig)");
        cleanup(chip, NULL, NULL);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(chip, ECHO_PIN, "echo", GPIOD_LINE_DIRECTION_INPUT, &echo);
    if (ret < 0) {
        perror("gpiod_line_request (echo)");
        cleanup(chip, trig, NULL);
        exit(EXIT_FAILURE);
    }

    // Set the trigger pin to low
    gpiod_line_set_value(trig, 0);

    while (1) {
        // Send a 10us pulse to the trigger pin
        gpiod_line_set_value(trig, 1);
        usleep(10000);
        gpiod_line_set_value(trig, 0);

        // Wait for the echo pin to go high
        while (gpiod_line_get_value(echo) == 0) {
            if (gpiod_line_get_value(echo) == 0) {
                printf("Echo pin did not respond within the expected time.\n");
                break;
            }
        }

        // Measure the duration of the echo pulse
        unsigned long start = gpiod_line_get_value(echo);
        unsigned long end = start;
        while (gpiod_line_get_value(echo) == 1) {
            end = gpiod_line_get_value(echo);
            if (end - start > 10000000) { // 10 seconds timeout
                printf("Echo pulse duration exceeded 10 seconds.\n");
                break;
            }
        }

        // Calculate the distance
        unsigned long duration = end - start;
        float distance = (duration * 34300) / 20000000; // Speed of sound = 343 m/s

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.1 seconds
        usleep(DELAY_MS * 1000);
    }

    // Cleanup on exit
    cleanup(chip, trig, echo);

    return 0;
}

