        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(GPIO_PINS[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpioSetMode(GPIO_PINS[j], PI_INPUT);
