        if (gpioSetPWMfrequency(GPIO_PINS[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpioSetMode(GPIO_PINS[j], PI_INPUT);
            }
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(GPIO_PINS[i], PWM_DUTY_CYCLE) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PINS[i]);
            for (int j = 0; j < i; j++) {
                gpioSetMode(GPIO_PINS[j], PI_INPUT);
            }
            gpioTerminate();
            return 1;
