#define I2C_ADDR 0x10
#define I2C_DEV "/dev/i2c-1"

int read_veml7700(int fd) {
    int ret;
    unsigned char data[2];

    // Read 2 bytes from VEML7700
    ret = read(fd, data, 2);
    if (ret != 2) {
        perror("Error reading from VEML7700");
        return -1;
    }

    // Combine the 2 bytes into a 16-bit value
    int reading = (data[0] << 8) | data[1];

    return reading;
}

int main() {
    int fd;

    // Open the I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    // Set the I2C address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    printf("Reading VEML7700 values every 0.5 seconds...\n");

    while (1) {
        int reading = read_veml7700(fd);
        if (reading >= 0) {
            printf("VEML7700 reading: %d\n", reading);
        }

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up on exit
    close(fd);

    return 0;
}

