int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    // Request GPIO lines
    trig_line = gpiod_line_request(chip, TRIG_PIN, "trig", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!trig_line) {
        handle_error("Failed to request TRIG line");
    }

    echo_line = gpiod_line_request(chip, ECHO_PIN, "echo", GPIOD_LINE_DIRECTION_INPUT);
    if (!echo_line) {
        handle_error("Failed to request ECHO line");
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            handle_error("Failed to read ECHO line");
        }

        if (ret == 0) {
            printf("Echo line is low, no valid reading.\n");
            continue;
        }

        // Calculate distance
        unsigned long long start_time = gpiod_line_get_value_timestamp(echo_line);
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            handle_error("Failed to read ECHO line");
        }

        if (ret == 0) {
            printf("Echo line is low, no valid reading.\n");
            continue;
        }

        unsigned long long end_time = gpiod_line_get_value_timestamp(echo_line);
        if (end_time < start_time) {
            printf("Invalid reading, end time is before start time.\n");
            continue;
        }

        unsigned long long duration = end_time - start_time;
        double distance = (duration * 343.0 / 2.0) / 1000000.0; // Speed of sound is approximately 343 m/s
        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.5 seconds
        sleep(1);
    }

    // Cleanup
    cleanup(chip, trig_line, echo_line);

    return 0;
}

