int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int distance;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    // Request TRIG_PIN as output
    trig_line = gpiod_line_request(chip, TRIG_PIN, "trig", GPIOD_LINE_DIRECTION_OUT);
    if (!trig_line) {
        handle_error("Failed to request TRIG_PIN");
    }

    // Request ECHO_PIN as input
    echo_line = gpiod_line_request(chip, ECHO_PIN, "echo", GPIOD_LINE_DIRECTION_IN);
    if (!echo_line) {
        handle_error("Failed to request ECHO_PIN");
    }

    // Set TRIG_PIN to low
    if (gpiod_line_set_value(trig_line, 0)) {
        handle_error("Failed to set TRIG_PIN low");
    }

    // Wait for 2ms
    usleep(2000);

    // Set TRIG_PIN to high
    if (gpiod_line_set_value(trig_line, 1)) {
        handle_error("Failed to set TRIG_PIN high");
    }

    // Wait for 10us
