    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for ECHO_PIN to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        // Wait for ECHO_PIN to go low
    }

    // Stop timing
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate time difference
    long long time_diff = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

    // Calculate distance
    distance = (time_diff / 2) / 29.1; // Speed of sound is approximately 343 m/s or 29.1 us/cm

    // Ensure distance is within the valid range
    if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

