#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 50
#define DELAY_SECONDS 5

int main(void) {
    int gpio_2_handle, gpio_3_handle, gpio_18_handle;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Set GPIO 2, 3, and 18 as output
    gpio_2_handle = gpioSetMode(GPIO_2, PI_OUTPUT);
    gpio_3_handle = gpioSetMode(GPIO_3, PI_OUTPUT);
    gpio_18_handle = gpioSetMode(GPIO_18, PI_OUTPUT);

    if (gpio_2_handle < 0 || gpio_3_handle < 0 || gpio_18_handle < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM on GPIO 18
    if (gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO 18.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(GPIO_18, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO 18.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        printf("PWM on GPIO 18: %d%%\n", PWM_DUTY_CYCLE);
        sleep(DELAY_SECONDS);
    }

    // Clean up
