}

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void cleanup(struct gpiod_chip *chip, struct gpiod_line *trigger_line, struct gpiod_line *echo_line) {
    if (trigger_line) {
        gpiod_line_free(trigger_line);
    }
    if (echo_line) {
        gpiod_line_free(echo_line);
    }
    if (chip) {
        gpiod_chip_put(chip);
    }
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int ret;

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    // Request trigger line (output)
    trigger_line = gpiod_line_request(chip, HC_SR04_TRIGGER_PIN, "HC-SR04 Trigger", 0, GPIOD_LINE_DIRECTION_OUT);
    if (!trigger_line) {
        handle_error("Failed to request trigger line");
    }

    // Request echo line (input)
    echo_line = gpiod_line_request(chip, HC_SR04_ECHO_PIN, "HC-SR04 Echo", 0, GPIOD_LINE_DIRECTION_IN);
    if (!echo_line) {
        handle_error("Failed to request echo line");
    }

    // Set trigger line to low
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret) {
        handle_error("Failed to set trigger line to low");
    }

    // Wait for 2ms
    usleep(2000);

    // Set trigger line to high
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret) {
        handle_error("Failed to set trigger line to high");
    }

    // Wait for 10us
    usleep(10);

    // Set trigger line to low
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret) {
        handle_error("Failed to set trigger line to low");
    }

    // Wait for echo line to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        if (gpiod_line_get_value(echo_line) == 0) {
            printf("Echo line did not go high within timeout.\n");
            cleanup(chip, trigger_line, echo_line);
            exit(EXIT_FAILURE);
        }
    }

    // Record start time
    struct timespec start_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    // Wait for echo line to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        if (gpiod_line_get_value(echo_line) == 1) {
            printf("Echo line did not go low within timeout.\n");
            cleanup(chip, trigger_line, echo_line);
            exit(EXIT_FAILURE);
        }
    }

    // Record end time
    struct timespec end_time;
    clock_gettime(CLOCK_REALTIME, &end_time);

    // Calculate time difference
    long long duration = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);

    // Calculate distance
    double distance = (duration / 2) / 299792458.0; // Speed of sound in m/s

    printf("Distance: %.2f cm\n", distance * 100);

    // Cleanup
    cleanup(chip, trigger_line, echo_line);

    return 0;
}

