        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        usleep(DELAY);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_release(line);
            gpiod_chip_put(chip);
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        usleep(DELAY);
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_put(chip);

    return EXIT_SUCCESS;
}

